<template><q-card flat bordered class="sessions-card"><q-card-section class="row items-center justify-between"><div class="section-title"><q-icon name="history"/> Historial de cajas</div><q-badge color="green-1" text-color="green-9" :label="`${sesiones.length} sesiones en esta página`"/></q-card-section><q-separator/><q-table flat :rows="sesiones" :columns="columns" row-key="idSesionCaja" :pagination="{rowsPerPage:6}" hide-pagination no-data-label="No hay sesiones de caja"><template #body-cell-fecha="p"><q-td :props="p"><div>{{p.row.fechaTexto}}</div><small>{{p.row.hora}}</small></q-td></template><template #body-cell-estado="p"><q-td :props="p"><q-badge :color="p.row.estado==='ABIERTA'?'positive':'grey-7'" :label="p.row.estado"/></q-td></template><template #body-cell-diferencia="p"><q-td :props="p" class="text-weight-bold" :class="p.row.diferencia===0?'text-positive':'text-orange-9'">{{p.row.diferencia<0?'-':''}}Bs {{Math.abs(p.row.diferencia).toFixed(2)}}</q-td></template><template #body-cell-acciones="p"><q-td :props="p"><q-btn flat round dense color="green-8" icon="visibility" @click="$emit('detalle',p.row)"><q-tooltip>Ver arqueo</q-tooltip></q-btn></q-td></template></q-table><q-card-actions v-if="totalPaginas>1" align="center" class="table-pager"><q-btn flat round icon="chevron_left" color="green-8" :disable="pagina<=1" aria-label="Página anterior" @click="$emit('pagina',pagina-1)"/><span>Página {{pagina}} de {{totalPaginas}}</span><q-btn flat round icon="chevron_right" color="green-8" :disable="pagina>=totalPaginas" aria-label="Página siguiente" @click="$emit('pagina',pagina+1)"/></q-card-actions></q-card></template>
<script setup>defineProps({sesiones:{type:Array,required:true},pagina:{type:Number,default:1},totalPaginas:{type:Number,default:1}});defineEmits(['detalle','pagina']);const columns=[{name:'fecha',label:'Fecha y hora',field:'fecha',align:'left'},{name:'caja',label:'Caja',field:'caja',align:'left'},{name:'cajero',label:'Cajero',field:'cajero',align:'left'},{name:'inicial',label:'Inicial',field:'inicial',format:v=>`Bs ${Number(v||0).toFixed(2)}`,align:'right'},{name:'esperado',label:'Esperado',field:'esperado',format:v=>`Bs ${Number(v||0).toFixed(2)}`,align:'right'},{name:'contado',label:'Contado',field:'contado',format:v=>`Bs ${Number(v||0).toFixed(2)}`,align:'right'},{name:'diferencia',label:'Diferencia',field:'diferencia',align:'right'},{name:'estado',label:'Estado',field:'estado',align:'center'},{name:'acciones',label:'',field:'acciones',align:'center'}]</script>
<style scoped>.sessions-card{border-radius:15px}.section-title{display:flex;align-items:center;gap:8px;color:#1b5e20;font-size:16px;font-weight:900}.sessions-card small{color:#789080;font-size:11px}.table-pager{gap:10px;color:#627167;font-size:13px;font-weight:700}</style>
